-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (601, '1', 'ASK 601: a judge never runs the same model as a debater',
  $t$A judge whose model is the same as either debater's model never sits: not on the panel, not as the reserve, and not as an alternate. This holds even when both debaters are Anthropic. The change goes LIVE (ruling 512). (plan rev 1, OBJECTIVE, ask601/w4/plan601.md 7aab840d)$t$,
  'in part',
  $t$Written by W4 at 12:19 CST 2026-11-24 (n8n updatedAt 18:19:50Z) on the card "Write it" pressed 12:18 CST in W4's thread (Wall 11652; audit 41585). Database first: odv1_record_panel_alternates 39d84307 to ad0d9e9c (new guard G-SAME, after G1 and before G2); dash_judge_lineup caea9e6c to e19ac69b (drops a same-model seat with its reason). Engine ff7ab4cf to 21316a8e-9107-4ba7-8966-230d20ad2d3f: two nodes changed, Init Seats 7949df51 to 0579c436 (drops from the free seats a seat whose model equals a debater's, reason "runs the same model as a debater (<model>)") and Resolve Seats 767dc7b0 to ffb7b688 (a panel judge with a debater's model stops the run; the reserve and the alternates skip such a seat). Child ecdc6218 unchanged; no prompt text and no model setting changed; nothing deleted. W1 readback MATCH (Wall 11654). Not shown by a run: no run has been made since the write, and the rule acts only when claude (anthropic/claude-sonnet-5.5) debates another Anthropic model, the one pair of active seats that shares a model. Shown offline: of the 90 debater pairs the engine accepts, 88 are unchanged and 2 change (claude against opus, both ways: sonnet dropped). Open: two clean live runs (the operator's rule of 10:38 CST 2026-11-24); revert601_db.sql is not rehearsed; the engine manual entry is drafted, not written.$t$,
  '11571, 11608, 11609, 11610, 11612, 11616, 11623, 11625, 11652, 11654',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$No sentence of the operator on ASK 601 is in the record W3 read. His part is two card presses in W4's thread. (1) The ruling card, asked 09:47 CST 2026-11-24: "Keep a judge out when it is the same model as a debater?"; he pressed "Keep same-model judges out" (15:48Z, Wall 11571; card cmsg_017ZQamDMHrS6fqMHnQDVo583pdnTfBZeZFqgAwoz5sr1g). (2) The write card, asked 11:48 CST: "Write the rule that keeps a judge off a debate its own model argues in?"; he pressed "Write it" at 12:18 CST (card cmsg_017ZQamDMHrS6fqMHnQDVo58WkaGgYMqcchHvLXpZA9N2g).$t$::text),
  $j${"answer": "Write it", "question": "Write the rule that keeps a judge off a debate its own model argues in?", "thread": "W4", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo58WkaGgYMqcchHvLXpZA9N2g", "press_time": "12:18 CST 2026-11-24 (18:18:58Z)", "source": "the card and its press read by W3 in W4's thread; Wall 11652", "ruling_card": {"card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo583pdnTfBZeZFqgAwoz5sr1g", "question": "Keep a judge out when it is the same model as a debater?", "answer": "Keep same-model judges out", "press_time": "09:48 CST 2026-11-24 (15:48Z)", "source": "Wall 11571"}}$j$::jsonb,
  'W4',
  $j${"md5": "7aab840d", "note": "rev 1 with W1's notes closed; rev 0 aebb13c0 (FAIL on form, Wall 11609), rev 1 first posted as 4ab3acd0", "path": "ask601/w4/plan601.md", "commit": "f5f708d8", "source": "Wall 11608, 11610, 11612, 11616; md5sum by W3 (7aab840de74cac6e0a9223bd8e37163f)"}$j$::jsonb,
  $j$[{"md5": "9cb87181", "path": "ask601/w4/b1/target_engine_601.json", "note": "the engine target; Init Seats 0579c436 (11,076 characters), Resolve Seats ffb7b688 (5,364 characters)", "source": "md5sum and node md5s by W3; W1 grade file"}, {"md5": "6baf9638", "path": "ask601/w4/b1/build601.cjs", "note": "builds the target from the live fetch", "source": "md5sum by W3"}, {"md5": "e8ab46de", "path": "ask601/w4/b1/fix601_db.sql", "note": "md5-gated exact replaces on the two functions", "source": "md5sum by W3"}, {"md5": "893bc98e", "path": "ask601/w4/b1/notes601.md", "note": "build notes", "source": "md5sum by W3; Wall 11623"}, {"md5": "46eb8e4d", "path": "ask601/w4/b1/t1_601.cjs", "note": "T1", "source": "md5sum by W3"}, {"md5": "83ffde15", "path": "ask601/w4/b1/t1b_601.cjs", "note": "T1b", "source": "md5sum by W3"}, {"md5": "860c5021", "path": "ask601/w4/b1/t_db_601.sql", "note": "T2, T3, T5", "source": "md5sum by W3"}, {"md5": "9efc8e1e", "path": "ask601/w4/b1/base_eng.json", "note": "live engine ff7ab4cf as fetched before the build", "source": "md5sum by W3"}, {"md5": "15c19fa1", "path": "ask601/w4/b1/fetchback_eng_601.json", "note": "fetch-back after the write, versionId 21316a8e-9107-4ba7-8966-230d20ad2d3f, active, 423 nodes", "source": "md5sum and read by W3"}]$j$::jsonb,
  $j${"engine": {"path": "ask601/w4/b1/revert_eng_601.json", "md5": "301edef5", "note": "the prior engine, saved by write601.sh at write time"}, "database": {"path": "ask601/w4/b1/revert601_db.sql", "md5": "13f861f3", "note": "NOT REHEARSED; gated on its anchors and on the restored md5s. W1's readback shows the fix file's replaces reverse on the live text to 39d84307 and caea9e6c exactly."}, "source": "notes601.md; Wall 11625 N1; Wall 11654; md5sum by W3"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "FAIL (form) (plan rev 0)", "wall_id": 11609, "md5_graded": "aebb13c0", "verdict_norm": "FAIL", "source": "Wall 11609 head"}, {"seat": "W1", "verdict": "PASS WITH N1, N2 (plan rev 1)", "wall_id": 11612, "md5_graded": "4ab3acd0", "verdict_norm": "PASS", "source": "Wall 11612"}, {"seat": "W1", "verdict": "notes CLOSED, PASS stands (plan)", "wall_id": 11616, "md5_graded": "7aab840d", "verdict_norm": "PASS", "source": "Wall 11616"}, {"seat": "W1", "verdict": "PASS WITH N1 TO N4 (build rev 0; W1 rebuilt the target 9cb87181 from its own fetch, 423 of 423 nodes equal)", "wall_id": 11625, "md5_graded": "9cb87181", "verdict_norm": "PASS", "source": "Wall 11625; fairjudge/w1/g601/grade_build601_rev0.md (commit 5e7ed949)"}]$j$::jsonb,
  ARRAY['9cb87181'], '[41585]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 moMxiV4Irg1uRBZN", "before": "ff7ab4cf", "after": "21316a8e-9107-4ba7-8966-230d20ad2d3f, active, 423 nodes"}, {"kind": "n8n node", "name": "Init Seats (engine, Code)", "before": "7949df51", "after": "0579c436, 11,076 characters"}, {"kind": "n8n node", "name": "Resolve Seats (engine, Code)", "before": "767dc7b0", "after": "ffb7b688, 5,364 characters"}, {"kind": "database function", "name": "odv1_record_panel_alternates", "before": "39d84307", "after": "ad0d9e9c"}, {"kind": "database function", "name": "dash_judge_lineup", "before": "caea9e6c", "after": "e19ac69b"}, {"kind": "n8n workflow, unchanged", "name": "child MqQHRl7mQQ0z8QdT", "before": "ecdc6218", "after": "ecdc6218"}]$j$::jsonb,
  $j$[{"name": "T1 (t1_601.cjs): live and target Init Seats plus Resolve Seats on the 90 debater pairs the engine accepts", "result": "88 equal; 2 differ (claude against opus, both ways): sonnet dropped \"runs the same model as a debater (anthropic/claude-sonnet-5.5)\"; no pair errors. The plan said 240 pairs; the engine accepts 90 (W1 N4).", "source": "notes601.md; W1's own run, Wall 11625"}, {"name": "T1b (t1b_601.cjs): sonnet put first on the panel list", "result": "live seats sonnet; the target fails closed with the reason", "source": "notes601.md; W1's own run, Wall 11625"}, {"name": "T2 (t_db_601.sql): dash_judge_lineup, live against new, 240 pairs", "result": "238 equal; the same 2 differ, with the same drop", "source": "notes601.md (W4's run; not rerun by W1)"}, {"name": "T3: odv1_record_panel_alternates, old and new, on temp copies of the 42234 and 42071 rows", "result": "one case changes: 42234 sol to sonnet, WRITTEN becomes RAISED G-SAME; the other five are the same (G1 raises twice, WRITTEN three times)", "source": "notes601.md (W4's run; not rerun by W1)"}, {"name": "T4: standing set and pair Library Check", "result": "29 of 29; pair PASSES", "source": "notes601.md; W1's own run, Wall 11625; at the write, Wall 11652"}, {"name": "T5: the new page copy against the target engine, 90 pairs", "result": "equal (md5 59457aaf both)", "source": "notes601.md (W4's run; not rerun by W1)"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "MATCH (engine 21316a8e active, 423 nodes, parameters and connections equal target_engine_601.json; against ff7ab4cf only Init Seats and Resolve Seats differ; child ecdc6218 untouched; odv1_record_panel_alternates ad0d9e9c, dash_judge_lineup e19ac69b; the fix file's replaces reversed on the live text give 39d84307 and caea9e6c)", "wall_id": 11654, "source": "Wall 11654; fairjudge/w1/g601/readback601.md (commit 1725ad0d)"}]$j$::jsonb,
  $j${"case": "NO PROBE (the plan states no ASK 417 registry entry exists for seat selection). UNEXERCISED: no run since the write. Mark: in a run where claude debates another Anthropic model, sonnet stands among the dropped seats with the reason \"runs the same model as a debater (anthropic/claude-sonnet-5.5)\" and does not sit. Two clean live runs are owed.", "source": "plan601.md RUN EVIDENCE (per Wall 11616); Wall 11654"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "NOT WRITTEN. Drafted: manual1123/w3/a601/em_pairs_601_draft1.json dbf275af (parts 03.0 and 10.0; new last entry of section 10, NO JUDGE RUNS A DEBATER'S MODEL), for W1's grade and then the operator's card."}$j$::jsonb,
  'read back', $j$[11571, 11608, 11609, 11610, 11612, 11616, 11623, 11625, 11652, 11654]$j$::jsonb)
RETURNING id)
INSERT INTO ask_aar_builders (snapshot_id, builder_seats, sources, written_by)
SELECT s.id, ARRAY['W4'], $j$[{"seat": "W4", "what": "planned, built and wrote ASK 601 (engine nodes Init Seats and Resolve Seats; database functions odv1_record_panel_alternates and dash_judge_lineup) on its card", "wall_id": 11652}]$j$::jsonb, current_setting('truth.session_id') FROM s;
SELECT * FROM ask_aar_snapshots_check() WHERE row_id = (SELECT max(id) FROM ask_aar_snapshots);
SELECT * FROM ask_aar_grades_check() WHERE snapshot_id = (SELECT max(id) FROM ask_aar_snapshots);
